root <- getwd()
args <- commandArgs(trailingOnly = TRUE)   # which: "sim" or "real"
if (args[1] == "sim") { dir.create("review/fixed_sim", showWarnings=FALSE); setwd("review/fixed_sim"); commandArgs <- function(...) file.path(root, "review/sim/data")
